<script setup lang="ts">
import {ref} from 'vue'
import type {Category} from './types'
import {useCatalogText} from './text'
import {displayName} from '../shared-commerce/format'
import {moduleRequest,ModuleApiError} from './api'
const props=defineProps<{base:string;categories:Category[];canEdit:boolean}>(),emit=defineEmits<{saved:[];busy:[boolean]}>(),{t,locale}=useCatalogText(),editing=ref<Category|null>(null),open=ref(false),busy=ref(false),error=ref(''),form=ref({code:'',nameZh:'',nameEn:'',enabled:true,sortOrder:0}),pending=ref<{path:string;method:string;body:Record<string,unknown>}|null>(null)
function edit(c?:Category){editing.value=c??null;form.value=c?{...c}:{code:'',nameZh:'',nameEn:'',enabled:true,sortOrder:0};open.value=true;emit('busy',true)}
async function save(){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';pending.value??={path:editing.value?`/categories/${editing.value.id}`:'/categories',method:editing.value?'PUT':'POST',body:{...form.value,expectedVersion:editing.value?.version??null,idempotencyKey:crypto.randomUUID()}};try{await moduleRequest(props.base,pending.value.path,pending.value.method,pending.value.body);pending.value=null;open.value=false;emit('saved')}catch(e){error.value=e instanceof Error?e.message:String(e);if(e instanceof ModuleApiError&&e.status<500)pending.value=null}finally{busy.value=false;emit('busy',open.value||!!pending.value)}}
</script>
<template><section class="cards-panel"><header class="cards-actions"><h2>{{t('categoryManage')}}</h2><button v-if="canEdit" :disabled="busy||!!pending" @click="edit()">＋ {{t('create')}}</button></header><p v-if="error" class="cards-error" role="alert">{{error}}</p><form v-if="open" @submit.prevent="save"><fieldset :disabled="busy||!!pending" style="border:0;padding:0"><div class="cards-grid"><label>{{t('code')}}<input v-model="form.code" :disabled="!!editing" required maxlength="80"></label><label>{{t('nameZh')}}<input v-model="form.nameZh"></label><label>{{t('nameEn')}}<input v-model="form.nameEn"></label><label class="check"><input v-model="form.enabled" type="checkbox">{{t('active')}}</label></div><div class="cards-actions"><button class="primary">{{t('save')}}</button><button type="button" @click="open=false;emit('busy',false)">{{t('cancel')}}</button></div></fieldset></form><button v-if="pending&&!busy" type="button" @click="save">{{t('recover')}}</button><div v-if="!open" class="cards-grid"><article v-for="c in categories" :key="c.id" class="cards-panel"><h3>{{displayName(c,locale)}}</h3><p>{{c.code}} · {{c.enabled?'✓':'—'}}</p><button v-if="canEdit" :disabled="busy||!!pending" @click="edit(c)">{{t('edit')}}</button></article></div></section></template>
